        foreach ($records as $record) {
            $crop = Crop::where('name', $record['crop_name'])->first();
            if (!$crop) continue;
            $pest = PestManagement::where('crop_id', $crop->id)->where('name', $record['name'])->first();
            if (!$pest) continue;
            $pest->crop_name_ur = $crop->name_ur;
            $pest->name_ur = $record['name_ur'];
            $pest->type_ur = $record['type_ur'];
            $pest->how_it_occurs_ur = $record['how_it_occurs_ur'];
            $pest->symptoms_ur = $record['symptoms_ur'];
            $pest->protection_ur = $record['protection_ur'];
            $pest->recommended_control_ur = $record['recommended_control_ur'];
            $pest->urdu_completed = collect([
                'crop_name_ur', 'name_ur', 'type_ur', 'how_it_occurs_ur',
                'symptoms_ur', 'protection_ur', 'recommended_control_ur',
            ])->every(fn ($field) => filled($pest->{$field}));
            $pest->save();
        }
    }
}
